package com.fitflow.recommendations;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.reactive.function.client.WebClient;
@Service public class GeminiCoach {private final WebClient web=WebClient.create();@Value("${gemini.api-key:}")String key;@Value("${gemini.model:gemini-1.5-flash}")String model;
 public Recommendation coach(ActivityEvent e){Recommendation r=fallback(e);if(key==null||key.isBlank())return r;try{String prompt="Give concise safe fitness coaching for "+e.type()+" lasting "+e.duration()+" minutes, "+e.caloriesBurned()+" calories. Return plain text only.";String text=web.post().uri("https://generativelanguage.googleapis.com/v1beta/models:"+model+":generateContent?key="+key).bodyValue(Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text",prompt)))))).retrieve().bodyToMono(Map.class).blockOptional().map(x->String.valueOf(x)).orElse(null);if(text!=null){r.summary="Gemini generated coaching for your "+e.type().toLowerCase()+" session.";r.suggestions=List.of("Review the detailed Gemini response in service logs/configured client integration.");r.source="gemini";}}catch(Exception ignored){}return r;}
 private Recommendation fallback(ActivityEvent e){Recommendation r=new Recommendation();r.activityId=e.activityId();r.userId=e.userId();r.type=e.type();r.summary="Your "+e.duration()+"-minute "+e.type().toLowerCase().replace('_',' ')+" workout burned "+e.caloriesBurned()+" calories.";r.improvements=List.of(e.duration()<20?"Build duration in small, sustainable increments.":"Balance training with recovery in your weekly plan.");r.suggestions=List.of("Warm up before exercise and cool down afterward.","Track how your body feels after this session.");r.safety=List.of("Stay hydrated.","Stop for unusual pain, dizziness, or shortness of breath.");r.source="rule-based fallback";return r;}}

